('<lesson_id>', 'match', replace($blk${"title": "Ты большой молодец! Осталось ещё пару заданий! Внимательно прочитай слова и найди продолжения предложений.", "pairs": [{"left": "I'm going to buy tickets to the", "right": "cinema tomorrow.", "right_audio_tts": "cinema tomorrow."}, {"left": "Are you going to come to my birthday", "right": "party next week?", "right_audio_tts": "party next week?"}, {"left": "My favourite singer is going to", "right": "sing at the concert this Friday.", "right_audio_tts": "sing at the concert this Friday."}, {"left": "I am going to wear a vampire costume", "right": "for a fancy dress party this Saturday.", "right_audio_tts": "for a fancy dress party this Saturday."}, {"left": "My best friend Kate is going to come to my house", "right": "for a sleepover this weekend.", "right_audio_tts": "for a sleepover this weekend."}, {"left": "They are going to take part in a", "right": "dance show at school next month.", "right_audio_tts": "dance show at school next month."}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 11),
('<lesson_id>', 'task', replace($blk${"title": "Дополнительное задание — для самых смелых! 💪", "needs_review": true, "html": "<p>Мне очень интересно, что ты и твоя семья планируете делать на каникулах. Письменно напиши 3 предложения о себе и 3 предложения о членах семьи.</p><p><i>Например: I am going to swim in the sea. My grandma is going to play golf.</i></p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 12),
('<lesson_id>', 'text', replace($blk${"html": "<p><img src=\"@@MEDIA@@shared/well_done_trophy.webp\" alt=\"\" style=\"height:180px\"></p><h3>Ура! 🎉</h3><p>Ты справился с домашней работой. Ты — большой молодец! Увидимся на занятии!</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 13),
